import { ApiProperty } from '@nestjs/swagger';
import { IsUUID } from 'class-validator';

export class StartRouteBatchDto {
  @ApiProperty({
    format: 'uuid',
    example: '01933b6e-7f2a-7c3d-9a1b-2f8e6c4d5a10',
    description:
      'UUID v7 generated by the driver app; retries with the same eventId do not start the route twice.',
  })
  @IsUUID('7')
  eventId!: string;
}
